select id, store_id, sum(quantity) over (partition by product_id order by quantity asc, id asc rows between unbounded preceding and current row) as cumulative_quantity, row_number() over (partition by product_id order by last_restock desc, id asc) as row_seq, row_number() over (partition by product_id order by quantity asc, id asc) as event_seq, rank() over (partition by store_id order by quantity desc nulls last) as quantity_rank from inventory where store_id in (1, 4, 6);
